        for (int r = 0; r < 12; ++r) {
            for (int c = 0; c < 12; ++c) {
                if (grid[r][c] == '1' && !vis[r][c]) {
                    islands++;
                    queue<pair<int,int>> q;
                    q.push({r, c});
                    vis[r][c] = 1;

                    while (!q.empty()) {
                        auto [x, y] = q.front();
                        q.pop();

                        for (int k = 0; k < 4; ++k) {
                            int nx = x + dr[k];
                            int ny = y + dc[k];
                            if (nx >= 0 && nx < 12 && ny >= 0 && ny < 12 &&
                                grid[nx][ny] == '1' && !vis[nx][ny]) {
                                vis[nx][ny] = 1;
                                q.push({nx, ny});
                            }
                        }
                    }
                }
            }
        }

        cout << islands << '\n';
    }

    return 0;
}

import java.util.Scanner;

public class Main {
    static int[][] grid = new int[12][12];
    static boolean[][] visited = new boolean[12][12];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            // Read 12 rows
            for (int i = 0; i < 12; i++) {
                int val = sc.nextInt();
                // val is a 12-bit binary number representing the row
                for (int j = 0; j < 12; j++) {
                    // bit 11-j represents column j
                    grid[i][j] = (val >> (11 - j)) & 1;
                }
            }

            // Reset visited
            for (int i = 0; i < 12; i++)
                for (int j = 0; j < 12; j++)
                    visited[i][j] = false;

            int count = 0;
            for (int i = 0; i < 12; i++) {
                for (int j = 0; j < 12; j++) {
                    if (grid[i][j] == 1 && !visited[i][j]) {
                        dfs(i, j);
                        count++;
                    }
                }
            }
            System.out.println(count);
        }
    }

    static void dfs(int r, int c) {
        if (r < 0 || r >= 12 || c < 0 || c >= 12) return;
        if (visited[r][c] || grid[r][c] == 0) return;
        visited[r][c] = true;
        dfs(r+1, c);
        dfs(r-1, c);
        dfs(r, c+1);
        dfs(r, c-1);
    }
}

