public class Main {
    static final int H = 12;
    static final int W = 12;

    static char[][] grid = new char[H][W];
    static boolean[][] visited = new boolean[H][W];

    static void dfs(int r, int c) {
        if (r < 0 || r >= H || c < 0 || c >= W) return;
        if (visited[r][c] || grid[r][c] != '#') return;

        visited[r][c] = true;

        dfs(r - 1, c);
        dfs(r + 1, c);
        dfs(r, c - 1);
        dfs(r, c + 1);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            String first = fs.next();
            if (first == null) break;

            for (int i = 0; i < H; i++) {
                String s = (i == 0) ? first : fs.next();
                for (int j = 0; j < W; j++) {
                    grid[i][j] = s.charAt(j);
                    visited[i][j] = false;
                }
            }

            int islands = 0;
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (grid[i][j] == '#' && !visited[i][j]) {
                        islands++;
                        dfs(i, j);
                    }
                }
            }

            out.append(islands).append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

