import sys
from collections import deque

def count_islands(grid):
    h, w = 12, 12
    visited = [[False] * w for _ in range(h)]
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    islands = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] == '1' and not visited[r][c]:
                islands += 1
                q = deque([(r, c)])
                visited[r][c] = True

                while q:
                    x, y = q.popleft()
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w:
                            if grid[nx][ny] == '1' and not visited[nx][ny]:
                                visited[nx][ny] = True
                                q.append((nx, ny))
    return islands

def main():
    lines = [line.strip() for line in sys.stdin if line.strip() != ""]
    if not lines:
        return

    idx = 0
    out = []

    # If the first line is the number of datasets, use it.
    # Otherwise, treat all input as consecutive 12-line datasets.
    if len(lines[0].split()) == 1 and lines[0].isdigit():
        t = int(lines[0])
        idx = 1
        for _ in range(t):
            grid = []
            while len(grid) < 12 and idx < len(lines):
                row = ''.join(ch for ch in lines[idx] if ch in '01')
                if len(row) == 12:
                    grid.append(row)
                idx += 1
            if len(grid) == 12:
                out.append(str(count_islands(grid)))
    else:
        while idx + 12 <= len(lines):
            grid = []
            for _ in range(12):
                row = ''.join(ch for ch in lines[idx] if ch in '01')
                grid.append(row)
                idx += 1
            if len(grid) == 12 and all(len(row) == 12 for row in grid):
                out.append(str(count_islands(grid)))

    sys.stdout.write("\n".join(out))

